sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_preset;
uniform float amzp_order;
uniform float amzp_completion;
uniform float amzp_revProg;
uniform float amzp_stepLen;
uniform float amzp_cols;
uniform float amzp_rows;
uniform float amzp_gap;
uniform float amzp_stagger;
uniform float amzp_orderRand;
uniform float amzp_rotX;
uniform float amzp_rotY;
uniform float amzp_rotZ;
uniform float amzp_rotRand;
uniform float amzp_depth;
uniform float amzp_scatter;
uniform float amzp_gravity;
uniform float amzp_shrink;
uniform float amzp_fade;
uniform float amzp_persp;
uniform float amzp_light;
uniform float amzp_back;
layout(color) uniform half4 amzp_backColor;
uniform float amzp_seed;
uniform float amzp_tileCols;
uniform float amzp_tileRows;
uniform float amzp_zoomAmt;
uniform float amzp_zoomVar;
uniform float amzp_quality;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float2 p, float k) { return fract(sin(dot(p, float2(127.1, 311.7)) + k * 17.31 + amzp_seed * 3.17) * 43758.5453); }
    float3x3 rotM(float3 a) {
        float cx = cos(a.x), sx = sin(a.x), cy = cos(a.y), sy = sin(a.y), cz = cos(a.z), sz = sin(a.z);
        float3x3 X = float3x3(1.0, 0.0, 0.0, 0.0, cx, sx, 0.0, -sx, cx);
        float3x3 Y = float3x3(cy, 0.0, -sy, 0.0, 1.0, 0.0, sy, 0.0, cy);
        float3x3 Z = float3x3(cz, sz, 0.0, -sz, cz, 0.0, 0.0, 0.0, 1.0);
        return Z * Y * X;
    }
    float4 srcAt(float2 Pg, float2 Wg, float2 W, float S, float aa) {
        float2 u = (Pg + Wg * 0.5) / Wg;
        return amzTexture(0, l2s(advRot((u - 0.5) * W * S, -aa) / W + 0.5));
    }
    float tileOrd(float2 nrm, float h1, bool ordered, float2 Wg, float M) {
        if (!ordered) return h1;
        float o;
        if (int(amzp_order) == 0) o = nrm.x;
        else if (int(amzp_order) == 1) o = 1.0 - nrm.x;
        else if (int(amzp_order) == 2) o = 1.0 - nrm.y;
        else if (int(amzp_order) == 3) o = nrm.y;
        else if (int(amzp_order) == 4) o = length((nrm - 0.5) * Wg / M) / length(0.5 * Wg / M);
        else if (int(amzp_order) == 5) o = 1.0 - length((nrm - 0.5) * Wg / M) / length(0.5 * Wg / M);
        else o = h1;
        return mix(o, h1, int(amzp_order) == 6 ? 0.0 : amzp_orderRand);
    }
    float4 zoomTiles(float2 P, float2 Wg, float2 W, float S, float aa, float M, float C) {
        float nc = clamp(floor(amzp_tileCols + 0.5), 1.0, 30.0), nr = clamp(floor(amzp_tileRows + 0.5), 1.0, 30.0);
        float2 ts = Wg / float2(nc, nr);
        float stg = clamp(amzp_stagger, 0.0, 0.95);
        float bestZ = -1.0;
        float4 col = float4(0.0);
        for (int j = 0; j < 30; j++) {
            if (float(j) >= nr) break;
            for (int i = 0; i < 30; i++) {
                if (float(i) >= nc) break;
                float2 cell = float2(float(i), float(j));
                float2 nrm = (cell + 0.5) / float2(nc, nr);
                float h1 = hh(cell, 1.0);
                float o = tileOrd(nrm, h1, int(amzp_preset) == 6, Wg, M);
                float del = o * stg;
                float tT = clamp((C - del) / max(1.0 - del, 0.001), 0.0, 1.0);
                float e = tT * tT * (3.0 - 2.0 * tT);
                float zPos = e * amzp_zoomAmt * (1.0 + (h1 - 0.5) * 2.0 * amzp_zoomVar);
                float sc = 2.0 / max(2.0 - zPos * 0.5, 0.001);
                if (zPos <= bestZ) continue;
                float2 c0 = (cell + 0.5) * ts - Wg * 0.5;
                float2 d = (P - c0 * sc) / sc;
                if (any(greaterThan(abs(d), ts * 0.5 * (1.0 - amzp_gap)))) continue;
                bestZ = zPos;
                float4 c = srcAt(c0 + d, Wg, W, S, aa);
                col = c * clamp(1.0 - e * amzp_fade, 0.0, 1.0);
            }
        }
        return col;
    }
    void amzRender() {
        float2 W = layer;
        float M = min(W.x, W.y);
        float S = max(amzp_advScale, 0.01);
        float aa = radians(amzp_advAngle);
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if ((amzp_revProg>0.5)) C = 1.0 - C;
        float2 P = advRot((amzLayerNorm() - 0.5) * W, aa) / S;
        float2 Wg = W;
        if (C <= 0.0) {
            float2 u0 = amzLayerNorm();
            amzOutput = (u0.x < 0.0 || u0.x > 1.0 || u0.y < 0.0 || u0.y > 1.0) ? float4(0.0) : amzTexture(0, l2s(u0));
            return;
        }
        if (int(amzp_preset) >= 5) {
            amzOutput = zoomTiles(P, Wg, W, S, aa, M, C);
            return;
        }
        float nc = max(floor(amzp_cols + 0.5), 1.0), nr = max(floor(amzp_rows + 0.5), 1.0);
        float2 ts = Wg / float2(nc, nr);
        float F = M * 2.0 * max(amzp_persp, 0.1);
        float3 E = float3(0.0, 0.0, -F);
        float3 D = float3(P, F);
        float2 cell0 = floor((P + Wg * 0.5) / ts);
        float R = amzp_quality;
        float best = 1e9;
        float4 col = float4(0.0);
        float stg = max(amzp_stagger, 0.0);
        for (int j = -4; j <= 4; j++) {
            if (abs(float(j)) > R) continue;
            for (int i = -4; i <= 4; i++) {
                if (abs(float(i)) > R) continue;
                float2 cell = cell0 + float2(float(i), float(j));
                if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= nc || cell.y >= nr) continue;
                float2 nrm = (cell + 0.5) / float2(nc, nr);
                float o;
                if (int(amzp_order) == 0) o = nrm.x;
                else if (int(amzp_order) == 1) o = 1.0 - nrm.x;
                else if (int(amzp_order) == 2) o = 1.0 - nrm.y;
                else if (int(amzp_order) == 3) o = nrm.y;
                else if (int(amzp_order) == 4) o = length((nrm - 0.5) * float2(Wg.x / M, Wg.y / M)) / length(0.5 * Wg / M);
                else if (int(amzp_order) == 5) o = 1.0 - length((nrm - 0.5) * float2(Wg.x / M, Wg.y / M)) / length(0.5 * Wg / M);
                else o = hh(cell, 9.0);
                o = mix(o, hh(cell, 1.0), int(amzp_order) == 6 ? 0.0 : amzp_orderRand);
                float pt;
                if (int(amzp_preset) == 0) {
                    pt = clamp(C * (1.0 + stg) - o * stg, 0.0, 1.0);
                } else {
                    float rT = nr - 1.0 - cell.y;
                    float N = max(nc * nr - 1.0, 1.0);
                    float rk;
                    if (int(amzp_order) == 0) rk = (cell.x * nr + rT) / N;
                    else if (int(amzp_order) == 1) rk = ((nc - 1.0 - cell.x) * nr + rT) / N;
                    else if (int(amzp_order) == 2) rk = (rT * nc + cell.x) / N;
                    else if (int(amzp_order) == 3) rk = (cell.y * nc + cell.x) / N;
                    else rk = o;
                    rk = mix(rk, hh(cell, 1.0), int(amzp_order) >= 4 ? 0.0 : amzp_orderRand * 0.15);
                    float sl = clamp(amzp_stepLen, 0.005, 1.0);
                    pt = clamp((C - rk * (1.0 - sl)) / sl, 0.0, 1.0);
                }
                if (pt <= 0.0) {
                    if (i == 0 && j == 0) {
                        float2 lp = P - ((cell + 0.5) * ts - Wg * 0.5);
                        if (best > 1.0 && all(lessThanEqual(abs(lp), ts * 0.5 * (1.0 - amzp_gap)))) {
                            float2 u = (P + Wg * 0.5) / Wg;
                            col = amzTexture(0, l2s(advRot((u - 0.5) * W * S, -aa) / W + 0.5));
                            best = 1.0;
                        }
                    }
                    continue;
                }
                float e = pt * pt;
                float3 r3 = float3(hh(cell, 2.0), hh(cell, 3.0), hh(cell, 4.0)) * 2.0 - 1.0;
                float3 ang = radians(float3(amzp_rotX, amzp_rotY, amzp_rotZ)) * (1.0 - amzp_rotRand + amzp_rotRand * r3) * e;
                float2 c0 = (cell + 0.5) * ts - Wg * 0.5;
                float2 sd = float2(hh(cell, 5.0), hh(cell, 6.0)) * 2.0 - 1.0;
                float3 T = float3(c0 + sd * amzp_scatter * ts * 3.0 * e + float2(0.0, -amzp_gravity * M * 0.6 * e * e * 1.4), amzp_depth * M * e * (0.6 + 0.8 * hh(cell, 7.0)));
                float sc = max(1.0 - amzp_shrink * e, 0.02);
                if (int(amzp_preset) != 0) {
                    float es = pt * pt * (3.0 - 2.0 * pt);
                    ang = float3(0.0);
                    sc = 1.0;
                    float z = 0.0;
                    if (int(amzp_preset) == 1 || int(amzp_preset) == 2) z = -0.72 * F * es;
                    if (int(amzp_preset) == 2) ang = float3(3.14159265 * es, 0.0, 0.0);
                    if (int(amzp_preset) == 3) z = 3.0 * F * es;
                    T = float3(c0 * (F + z) / F, z);
                    if (int(amzp_preset) == 4) T = float3(c0 + float2(0.0, -Wg.y * 1.2 * pt * pt), M * 0.3 * es);
                }
                float3x3 Rm = rotM(ang);
                float3 n = Rm * float3(0.0, 0.0, 1.0);
                float dn = dot(D, n);
                if (abs(dn) < 1e-5) continue;
                float t = dot(T - E, n) / dn;
                if (t <= 0.0 || t >= best) continue;
                float3 hit = E + t * D;
                float3 loc = (hit - T) * Rm;
                float2 lp = loc.xy / sc;
                if (any(greaterThan(abs(lp), ts * 0.5 * (1.0 - amzp_gap)))) continue;
                float2 u = (c0 + lp + Wg * 0.5) / Wg;
                float4 c = amzTexture(0, l2s(advRot((u - 0.5) * W * S, -aa) / W + 0.5));
                bool backFace = dot(n, D) < 0.0;
                if (backFace && int(amzp_back) == 1) c = float4(amzp_backColor.rgb, 1.0) * c.a;
                float sh = 1.0 - amzp_light * (1.0 - abs(n.z));
                c.rgb *= sh;
                c *= 1.0 - (int(amzp_preset) == 0 ? amzp_fade : 1.0) * smoothstep(int(amzp_preset) == 0 ? 0.55 : 0.45, 1.0, pt);
                col = c;
                best = t;
            }
        }
        amzOutput = col;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
